from pathlib import Path
import subprocess

root=Path(__file__).resolve().parents[1]
engine=root/'anclab/src/main/java/com/p38/anclab/audio/AudioEngine.java'
main=root/'anclab/src/main/java/com/p38/anclab/MainActivity.java'
test=root/'anclab/src/test/java/com/p38/anclab/dsp/FixedToneCancellationLabTest.java'
