# Restore AudioEngine from the known-good commit immediately before the accidental overwrite.
restored=subprocess.check_output(['git','show','c7b07e477d2ac71130dd336f2737c2b70f6aff63:anclab/src/main/java/com/p38/anclab/audio/AudioEngine.java'],text=True)

def one(s,old,new,label):
    if s.count(old)!=1: raise RuntimeError(f'{label}: {s.count(old)} matches')
    return s.replace(old,new,1)

s=restored
s=one(s,'public boolean isFixedToneLab(){return mode==Mode.TONE_LAB&&running.get();}',
'''public boolean isFixedToneLab(){return mode==Mode.TONE_LAB&&running.get();}\n    public double getFixedToneLabFrequencyHz(){FixedToneCancellationLab lab=fixedToneLab;return lab==null?Double.NaN:lab.targetFrequencyHz();}''','engine frequency getter')
old='''    /** Fixed 120 Hz physical-search bench mode. No route calibration, telemetry or recipes. */\n    @SuppressLint("MissingPermission")\n    public synchronized boolean startFixedToneLab120(){\n        if(running.get())return true;\n        try{\n            mode=Mode.TONE_LAB;activeProfile="120HZ_LAB";vehicleBroadbandEnabled=false;safetyStatus="";lastError="None";digitalSilenceFrames=0;\n            record=buildRecord();track=buildTrack();if(record==null||track==null)throw new IllegalStateException("Could not open selected audio route");\n            clearGraph();record.startRecording();track.play();track.write(new float[192],0,192,AudioTrack.WRITE_BLOCKING);\n            AudioDeviceInfo routed=track.getRoutedDevice();expectedOutputRouteId=routed==null?0:routed.getId();routeMissingBlocks=0;routeGainCompensation=1f;\n            fixedToneLab=new FixedToneCancellationLab();fixedToneLab.setUserOutputScale(antiNoisePercent/100f);\n            stationaryNoiseProfiler.reset();running.set(true);if(monitorLogEnabled)monitoringLog.start();\n            worker=new Thread(this::runLoop,"ANC-Lab-120Hz");worker.setPriority(Thread.MAX_PRIORITY);worker.start();\n            safetyStatus="120 Hz lab · muted A/B physical search starting";AppLog.i(TAG,"120 Hz cancellation lab started route="+outputRoute+" limit="+antiNoisePercent+"%");return true;\n        }catch(Exception e){lastError=e.getMessage();AppLog.e(TAG,"120 Hz lab start failed",e);stop();return false;}\n    }\n'''
new='''    /** Fixed-frequency physical-search bench mode. No route calibration, telemetry or recipes. */\n    @SuppressLint("MissingPermission")\n    public synchronized boolean startFixedToneLab(double frequencyHz){\n        if(running.get())return true;\n        try{\n            mode=Mode.TONE_LAB;activeProfile=String.format(Locale.US,"%.0fHZ_LAB",frequencyHz);vehicleBroadbandEnabled=false;safetyStatus="";lastError="None";digitalSilenceFrames=0;\n            record=buildRecord();track=buildTrack();if(record==null||track==null)throw new IllegalStateException("Could not open selected audio route");\n            clearGraph();record.startRecording();track.play();track.write(new float[192],0,192,AudioTrack.WRITE_BLOCKING);\n            AudioDeviceInfo routed=track.getRoutedDevice();expectedOutputRouteId=routed==null?0:routed.getId();routeMissingBlocks=0;routeGainCompensation=1f;\n            fixedToneLab=new FixedToneCancellationLab(frequencyHz);fixedToneLab.setUserOutputScale(antiNoisePercent/100f);\n            stationaryNoiseProfiler.reset();running.set(true);if(monitorLogEnabled)monitoringLog.start();\n            worker=new Thread(this::runLoop,"ANC-Lab-FixedTone");worker.setPriority(Thread.MAX_PRIORITY);worker.start();\n            safetyStatus=String.format(Locale.US,"%.0f Hz lab · muted A/B physical search starting",frequencyHz);AppLog.i(TAG,String.format(Locale.US,"%.0f Hz cancellation lab started route=%s limit=%d%%",frequencyHz,outputRoute,antiNoisePercent));return true;\n        }catch(Exception e){lastError=e.getMessage();AppLog.e(TAG,"Fixed-tone lab start failed",e);stop();return false;}\n    }\n'''
s=one(s,old,new,'generalize lab start')
s=s.replace('"FIXED_120HZ_PHYSICAL_PHASE_GAIN_SEARCH"','"FIXED_TONE_PHYSICAL_PHASE_GAIN_SEARCH"')
