old='''    private void toggleToneLab(){\n        if(rt.audio.isRunning()){stopAnc();return;}if(!hasAudioPermission()){requestAudioPermissionIfNeeded();return;}\n        boolean ok=rt.audio.startFixedToneLab120();if(ok){Intent s=new Intent(this,AncMediaService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(s);else startService(s);updateProfileUi();toast("120 Hz lab started · keep the test tone steady and start a WAV recording");}else toast("Could not start 120 Hz lab: "+rt.audio.getLastError());\n    }\n'''
new='''    private void toggleToneLab(){\n        if(rt.audio.isRunning()){stopAnc();return;}if(!hasAudioPermission()){requestAudioPermissionIfNeeded();return;}\n        double[] f={45,65,90,120,160,250,500};int pos=toneLabFrequencySpinner==null?3:toneLabFrequencySpinner.getSelectedItemPosition();double hz=f[Math.max(0,Math.min(f.length-1,pos))];\n        boolean ok=rt.audio.startFixedToneLab(hz);if(ok){Intent s=new Intent(this,AncMediaService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(s);else startService(s);updateProfileUi();toast(String.format(Locale.US,"%.0f Hz lab started · keep that test tone steady and start a WAV recording",hz));}else toast("Could not start fixed-tone lab: "+rt.audio.getLastError());\n    }\n'''
