s=s.replace('String session=rt.audio.isFixedToneLab()?"120 Hz cancellation lab":profileName();','String session=rt.audio.isFixedToneLab()?String.format(Locale.US,"%.0f Hz cancellation lab",rt.audio.getFixedToneLabFrequencyHz()):profileName();')
